const G = 9.8, S = 100, Y0 = 190, VS = 18, AS = 4;
const XT = 230, XH = 430;
function fx(v) { const r = Math.abs(v) < 0.005 ? 0 : v; return sdk.format(r, 2); }
export function evaluate({ inputs, time }) {
  let u = Number(inputs && inputs.launchSpeed);
  if (!isFinite(u)) u = 3;
  u = sdk.clamp(u, 3, 5);
  const show = !(inputs && inputs.showArrows === 'off');
  const T = u / G, end = 2 * T;
  const t = sdk.clamp(Number(time) || 0, 0, end);
  const h = u * t - G * t * t / 2;
  const v = u - G * t;
  const a = -G;
  const released = t >= T;
  const td = Math.max(0, t - T);
  const hh = -G * td * td / 2;
  const hv = released ? -G * td : 0;
  const ha = released ? -G : 0;
  const apexH = u * u / (2 * G);
  const yT = Y0 - h * S, yH = Y0 - hh * S, yA = Y0 - apexH * S;
  const o = [];
  o.push(sdk.line('axis', 90, 40, 90, 425, { role: 'neutral' }));
  o.push(sdk.text('axisLabel', 90, 30, 'height', { align: 'middle' }));
  [[1, 'm1'], [0, 'z0'], [-1, 'n1']].forEach(([m, k]) => {
    const y = Y0 - m * S;
    o.push(sdk.line('tick' + k, 84, y, 96, y, { role: 'neutral' }));
    o.push(sdk.text('tickL' + k, 44, y + 5, m + ' m'));
  });
  o.push(sdk.line('launchLine', 100, Y0, 470, Y0, { role: 'neutral', opacity: 0.6 }));
  o.push(sdk.text('launchLabel', 105, Y0 - 8, 'launch'));
  o.push(sdk.line('apexLine', XT + 32, yA, XT + 100, yA, { role: 'success', opacity: 0.8 }));
  o.push(sdk.text('apexLabel', XT + 106, yA + 5, 'top: ' + sdk.format(apexH, 2) + ' m, ' + sdk.format(T, 2) + ' s'));
  o.push(sdk.text('titleT', XT, 24, 'Tossed ball', { align: 'middle' }));
  o.push(sdk.text('titleH', XH, 24, 'Held ball', { align: 'middle' }));
  const PX = XH + 46;
  if (released) {
    o.push(sdk.line('gate', PX, Y0 + 12, PX, Y0 + 46, { role: 'warning' }));
  } else {
    o.push(sdk.line('gate', XH - 14, Y0 + 12, PX, Y0 + 12, { role: 'warning' }));
  }
  o.push(sdk.box('gatePivot', PX - 4, Y0 + 8, 8, 8, { role: 'warning' }));
  o.push(sdk.text('gateLabel', PX + 8, Y0 + 32, released ? 'gate open' : 'gate'));
  o.push(sdk.circle('tossedBall', XT, yT, 22, { role: 'observed' }));
  o.push(sdk.circle('heldBall', XH, yH, 22, { role: 'input' }));
  function arrows(p, x, y, vel, acc) {
    const L = vel * VS;
    if (Math.abs(L) < 4) {
      o.push(sdk.circle(p + 'vDot', x - 20, y, 8, { role: 'output' }));
      o.push(sdk.text(p + 'vL', x - 20, y - 12, 'v', { align: 'middle' }));
    } else {
      o.push(sdk.arrow(p + 'v', x - 20, y, x - 20, y - L, { role: 'output' }));
      o.push(sdk.text(p + 'vL', x - 42, y - L / 2 + 5, 'v'));
    }
    if (acc !== 0) {
      const A = acc * AS;
      o.push(sdk.arrow(p + 'a', x + 20, y, x + 20, y - A, { role: 'warning' }));
      o.push(sdk.text(p + 'aL', x + 26, y - A / 2 + 5, 'a'));
    }
  }
  if (show) { arrows('t', XT, yT, v, a); arrows('h', XH, yH, hv, ha); }
  const X = 500;
  o.push(sdk.text('valT', X, 70, 'Tossed'));
  o.push(sdk.text('valTh', X, 94, 'h = ' + fx(h) + ' m'));
  o.push(sdk.text('valTv', X, 118, 'v = ' + fx(v) + ' m/s'));
  o.push(sdk.text('valTa', X, 142, 'a = ' + fx(a) + ' m/s²'));
  o.push(sdk.text('valH', X, 270, released ? 'Held (falling)' : 'Held (on gate)'));
  o.push(sdk.text('valHv', X, 294, 'v = ' + fx(hv) + ' m/s'));
  o.push(sdk.text('valHa', X, 318, 'a = ' + fx(ha) + ' m/s²'));
  const readouts = [
    { id: 'tossedHeight', value: h },
    { id: 'tossedVelocity', value: v },
    { id: 'tossedAcceleration', value: a }
  ];
  return {
    frame: { width: 640, height: 440, objects: o, readouts },
    quantities: {
      launchSpeed: u, gravity: G, velocity: v, acceleration: a, apexTime: T, height: h,
      tossedHeight: h, tossedVelocity: v, tossedAcceleration: a,
      heldHeight: hh, heldVelocity: hv, heldAcceleration: ha, apexHeight: apexH
    }
  };
}
